// Site pages: Our Story, Mission & Vision, Strategy & Objectives, Our Team, and the texts of the Partners page.
// Listed in Website › Pages (PagesList) and opened at /studio/pages/site/<key>. A visual editor like the Homepage's:
// the page's sections on the left (show, hide, reorder), the real page in the middle (generated by src/content.py from
// the unsaved draft; click a section to edit it), its fields on the right. Every change goes through review
// (draft → in review → approved → published), like any other record.
import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react';
import { api, post, put, ApiError } from '../api.ts';
import { Badge, Icon, Link, LiveBadge, Modal, fmtDate, navigate, useCan, useMe, useToast } from '../ui.tsx';
import { Field } from '../Editor.tsx';
import { MediaPicker, type MediaItem } from './Media.tsx';
import { Loading } from './Dashboard.tsx';
import '../pillars.css';
import '../about.css';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Content = Record<string, any>;
type Loaded = { id: string; key: string; status: string; publishedRevisionId: string | null; publishedAt: string | null; verifiedAt: string | null; provenance: string; content: Content | null;
  meta: { title: string; file: string; desc: string }; media: MediaItem[]; problems: string[];
  context: { pillars: { key: string; name: string }[]; objectives: { ref: string; pillarKeys: string[] }[]; groups: { value: string; label: string }[]; publicEmails: string[]; sections: Record<string, Record<string, string | boolean>> };
  history: { revisions: { id: string; number: number; reason: string; createdAt: string }[]; comments: { id: string; kind: string; body: string; createdAt: string }[] } };

// ---------------------------------------------------------------- small form helpers (paths into the content object)
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const getAt = (o: Content, path: (string | number)[]): any => path.reduce((x: Content | undefined, k) => (x == null ? undefined : x[k as never]), o);
function setAt(o: Content, path: (string | number)[], v: unknown): Content {
  const n = structuredClone(o); let x: Content = n;
  path.slice(0, -1).forEach((k, i) => { if (x[k as never] == null) (x as Record<string, unknown>)[k as never] = typeof path[i + 1] === 'number' ? [] : {}; x = x[k as never]; });
  (x as Record<string, unknown>)[path[path.length - 1] as never] = v; return n;
}
type Ctx = { f: Content; set: (path: (string | number)[], v: unknown) => void; editable: boolean };

function TextF({ c, path, label, max, rows, hint, span = 3, big }: { c: Ctx; path: (string | number)[]; label: string; max: number; rows?: number; hint?: ReactNode; span?: 1 | 2 | 3; big?: boolean }) {
  const v = String(getAt(c.f, path) ?? '');
  return <Field label={label} span={span} count={[v.length, max]} hint={hint}>
    {rows ? <textarea className="textarea" rows={rows} maxLength={max} value={v} onChange={(e) => c.set(path, e.target.value)} aria-label={label} />
      : <input className={`input${big ? ' input-lg' : ''}`} maxLength={max} value={v} onChange={(e) => c.set(path, e.target.value)} aria-label={label} />}
  </Field>;
}

type FieldSpec = { k: string; label: string; max: number; rows?: number; placeholder?: string; required?: boolean };
/** A repeatable list of small records (milestones, principles, people…): numbered rows that move, and can be removed. */
function Repeat({ c, path, label, noun, max, fields, blank, extra, fixed, head }: {
  c: Ctx; path: (string | number)[]; label: string; noun: string; max: number; fields: FieldSpec[]; blank?: Content;
  extra?: (item: Content, i: number) => ReactNode; fixed?: boolean; head?: (item: Content, i: number) => ReactNode;
}) {
  const items: Content[] = getAt(c.f, path) ?? [];
  const move = (i: number, d: -1 | 1) => { const n = [...items]; [n[i], n[i + d]] = [n[i + d], n[i]]; c.set(path, n); };
  return <div className="field ed-f s3"><span className="ed-lbl">{label}</span>
    {items.length === 0 && <p className="muted" style={{ margin: 0 }}>None yet.</p>}
    {items.length > 0 && <ol className="pl-steps ab-rows">{items.map((it, i) => <li key={i}>
      <span className="pl-step-n">{head ? head(it, i) : String(i + 1).padStart(2, '0')}</span>
      <div className="pl-step-f">
        {fields.map((fs) => {
          const v = String(it[fs.k] ?? ''); const lab = `${noun} ${i + 1}: ${fs.label}`;
          return fs.rows ? <textarea key={fs.k} className="textarea" rows={fs.rows} maxLength={fs.max} value={v} placeholder={fs.placeholder ?? fs.label} onChange={(e) => c.set([...path, i, fs.k], e.target.value)} aria-label={lab} />
            : <input key={fs.k} className="input" maxLength={fs.max} value={v} placeholder={fs.placeholder ?? fs.label} onChange={(e) => c.set([...path, i, fs.k], e.target.value)} aria-label={lab} aria-invalid={fs.required && !v.trim() ? true : undefined} />;
        })}
        {extra?.(it, i)}
      </div>
      {!fixed && <span className="pl-step-a">
        <button type="button" className="btn btn-ghost icon-btn btn-sm" disabled={i === 0} onClick={() => move(i, -1)} aria-label={`Move ${noun.toLowerCase()} ${i + 1} up`}>↑</button>
        <button type="button" className="btn btn-ghost icon-btn btn-sm" disabled={i === items.length - 1} onClick={() => move(i, 1)} aria-label={`Move ${noun.toLowerCase()} ${i + 1} down`}>↓</button>
        <button type="button" className="btn btn-ghost icon-btn btn-sm" onClick={() => c.set(path, items.filter((_, j) => j !== i))} aria-label={`Remove ${noun.toLowerCase()} ${i + 1}`}><Icon n="x" /></button></span>}
    </li>)}</ol>}
    {!fixed && (items.length < max ? <button type="button" className="btn btn-sm" style={{ justifySelf: 'start' }} onClick={() => c.set(path, [...items, blank ?? Object.fromEntries(fields.map((x) => [x.k, '']))])}><Icon n="plus" />Add {noun.toLowerCase()}</button>
      : <small>{max} is the maximum.</small>)}
  </div>;
}

/** Paragraphs: a list of plain-text blocks. */
function Paras({ c, path, label, max, maxItems, hint }: { c: Ctx; path: (string | number)[]; label: string; max: number; maxItems: number; hint?: ReactNode }) {
  const items: string[] = getAt(c.f, path) ?? [];
  return <div className="field ed-f s3"><span className="ed-lbl">{label}</span>
    <ol className="pl-steps ab-rows">{items.map((p, i) => <li key={i}><span className="pl-step-n">{String(i + 1).padStart(2, '0')}</span>
      <div className="pl-step-f"><textarea className="textarea" rows={3} maxLength={max} value={p} onChange={(e) => c.set([...path, i], e.target.value)} aria-label={`${label}, paragraph ${i + 1}`} /></div>
      <span className="pl-step-a"><button type="button" className="btn btn-ghost icon-btn btn-sm" onClick={() => c.set(path, items.filter((_, j) => j !== i))} aria-label={`Remove paragraph ${i + 1}`}><Icon n="x" /></button></span></li>)}</ol>
    {items.length < maxItems && <button type="button" className="btn btn-sm" style={{ justifySelf: 'start' }} onClick={() => c.set(path, [...items, ''])}><Icon n="plus" />Add a paragraph</button>}
    {hint && <small>{hint}</small>}
  </div>;
}

function Photo({ c, path, media, pick, label, small }: { c: Ctx; path: (string | number)[]; media: Map<string, MediaItem>; pick: (path: (string | number)[]) => void; label: string; small?: boolean }) {
  const id = getAt(c.f, path) as string | null; const m = id ? media.get(id) : undefined;
  if (!id) return <button type="button" className={`ed-drop${small ? ' ab-drop-sm' : ''}`} disabled={!c.editable} onClick={() => pick(path)}><Icon n="image" /><b>{label}</b>{!small && <small>From the media library.</small>}</button>;
  return <div className={`ab-photo${small ? ' is-sm' : ''}`}>
    {m ? <img src={m.url} alt={m.alt} /> : <span className="ab-photo-missing">Photo</span>}
    <span className="ab-photo-meta">
      {m && <span className={m.alt ? 'ok' : 'warn'}><Icon n={m.alt ? 'check' : 'alert'} width={13} height={13} />{m.alt ? 'Alt text' : 'No alt text'}</span>}
      {m && <span className={m.rightsConfirmed ? 'ok' : 'warn'}><Icon n={m.rightsConfirmed ? 'check' : 'alert'} width={13} height={13} />{m.rightsConfirmed ? 'Rights confirmed' : 'Rights not confirmed'}</span>}
      <span className="ab-photo-a"><button type="button" className="btn btn-sm" disabled={!c.editable} onClick={() => pick(path)}>Change</button><button type="button" className="btn btn-sm btn-ghost" disabled={!c.editable} onClick={() => c.set(path, null)}>Remove</button></span>
    </span>
  </div>;
}

// ---------------------------------------------------------------- section headings (built-in text unless edited)
const SECTION_FIELDS: [string, string, number, string][] = [
  ['tab', 'Menu label', 40, 'In the sticky menu under the overview.'], ['label', 'Small label', 60, 'Next to the section number.'],
  ['title', 'Heading', 120, 'Written in black.'], ['soft', 'Heading, second part', 120, 'Written in grey. Leave empty for none.'],
  ['meta', 'Note on the right', 60, 'Short note at the end of the label line. Leave empty for none.'], ['desc', 'Description', 400, 'One or two lines beside the heading.'],
  ['sub', 'Sub-heading', 60, 'Small heading inside the section.'], ['sub2', 'Second sub-heading', 60, 'Small heading inside the section.'],
];
type Defs = Record<string, Record<string, string | boolean>>;
const ownCfg = (c: Ctx, id: string) => (c.f.sections?.[id] ?? null) as Record<string, string | boolean> | null;
const secVal = (c: Ctx, defs: Defs, id: string, k: string) => (ownCfg(c, id)?.[k] ?? defs[id]?.[k] ?? '') as string;
function setSec(c: Ctx, defs: Defs, id: string, k: string, v: string | boolean) {
  const { fixed: _f, ...d } = defs[id] ?? {};
  c.set(['sections', id], { show: true, ...d, ...(ownCfg(c, id) ?? {}), [k]: v });
}
/** The heading texts of one section, with a reset to the built-in wording. */
function SectionTexts({ c, defs, id }: { c: Ctx; defs: Defs; id: string }) {
  const fields = SECTION_FIELDS.filter(([k]) => defs[id] && k in defs[id]);
  if (!fields.length) return null;
  return <details className="ab-heads" open><summary>Heading and menu</summary>
    <div className="stack" style={{ gap: 10 }}>{fields.map(([k, lab, max, hint]) => <Field key={k} label={lab} count={[secVal(c, defs, id, k).length, max]} hint={hint}>
      {k === 'desc' ? <textarea className="textarea" rows={2} maxLength={max} value={secVal(c, defs, id, k)} onChange={(e) => setSec(c, defs, id, k, e.target.value)} aria-label={lab} />
        : <input className="input" maxLength={max} value={secVal(c, defs, id, k)} onChange={(e) => setSec(c, defs, id, k, e.target.value)} aria-label={lab} />}</Field>)}
      {ownCfg(c, id) && Object.keys(ownCfg(c, id)!).some((k) => k !== 'show') && <button type="button" className="btn btn-sm btn-ghost" style={{ justifySelf: 'start' }} onClick={() => c.set(['sections', id], ownCfg(c, id)?.show === false ? { show: false } : undefined)}><Icon n="undo" />Reset to built-in text</button>}
    </div></details>;
}

// ---------------------------------------------------------------- the visual editor
type Item = { id: string; label: string; icon: string; kind: 'page' | 'fixed' | 'section' };
const DEVICES = [[1280, 'monitor', 'Desktop'], [820, 'tablet', 'Tablet'], [390, 'phone', 'Mobile']] as const;
const ICONS: Record<string, string> = { statement: 'users', journey: 'calendar', different: 'check', 'what-we-do': 'pillars', approach: 'layers', impact: 'spark',
  mission: 'send', values: 'check', vision: 'eye', next: 'ext', objectives: 'check', 'who-we-serve': 'users', 'where-we-work': 'pin', directory: 'partner', models: 'layers', how: 'send',
  board: 'users', executive: 'users', staff: 'users', volunteers: 'heart' };
/** Where a click on the canvas lands: the page header, the overview, a section (by its id) or the closing band. */
const CANVAS_TARGETS = '.page-head, #overview, section[id], li.abx-path-i[id], .cta-wrap';

export function AboutEditor({ refKey }: { refKey: string; onChanged?: () => void }) {
  const can = useCan(); const me = useMe(); const toast = useToast();
  const [p, setP] = useState<Loaded | null>(null); const [f, setF] = useState<Content | null>(null);
  const [media, setMedia] = useState<Map<string, MediaItem>>(new Map());
  const [dirty, setDirty] = useState(false); const [busy, setBusy] = useState(''); const [errs, setErrs] = useState<string[]>([]);
  const [dialog, setDialog] = useState<null | 'preview' | 'publish' | 'changes' | 'history'>(null); const [picking, setPicking] = useState<(string | number)[] | null>(null);
  const [url, setUrl] = useState(''); const [comment, setComment] = useState('');
  const [sel, setSel] = useState<string | null>(null); const [html, setHtml] = useState('');
  const [device, setDevice] = useState<number>(1280); const [size, setSize] = useState({ w: 800, h: 600 });
  const frame = useRef<HTMLIFrameElement>(null); const box = useRef<HTMLDivElement>(null); const scrollY = useRef(0); const fromCanvas = useRef(false);
  const load = useCallback(async () => {
    const d = await api<Loaded>(`/about/${refKey}`);
    setP(d); setF(d.content ? structuredClone(d.content) : null); setMedia(new Map(d.media.map((m) => [m.id, m]))); setDirty(false);
  }, [refKey]);
  useEffect(() => { load().catch((e) => toast(e.message, true)); }, [load]);
  // the canvas: the real page with the unsaved draft, regenerated shortly after each change
  useEffect(() => {
    if (!p || !f) return;
    const t = setTimeout(() => { post<{ html: string }>(`/about/${p.key}/canvas`, { content: f }).then((r) => setHtml(r.html)).catch((e) => setErrs([e.message])); }, 300);
    return () => clearTimeout(t);
  }, [f, p?.key]);
  useEffect(() => { const el = box.current; if (!el) return; const ro = new ResizeObserver(() => setSize({ w: el.clientWidth, h: el.clientHeight })); ro.observe(el); return () => ro.disconnect(); }, [!!p, !!f]);
  const idOf = (el: HTMLElement) => el.classList.contains('page-head') ? 'hero' : el.classList.contains('cta-wrap') ? 'closing' : el.id;
  const wire = useCallback(() => {
    const doc = frame.current?.contentDocument; if (!doc) return;
    doc.querySelectorAll<HTMLElement>(CANVAS_TARGETS).forEach((el) => {
      const id = idOf(el); if (!id || (el.tagName === 'SECTION' && el.closest('li.abx-path-i'))) return;
      el.dataset.ab = id; el.classList.toggle('is-selected', id === sel);
      el.onclick = (e) => { e.preventDefault(); e.stopPropagation(); fromCanvas.current = true; setSel(id); };
    });
    const win = frame.current?.contentWindow; if (win) win.onscroll = () => { scrollY.current = win.scrollY; };
  }, [sel]);
  const reveal = useCallback(() => {
    const el = frame.current?.contentDocument?.querySelector<HTMLElement>(`[data-ab="${sel}"]`); const win = frame.current?.contentWindow;
    if (!el || !win) return;
    const top = Math.max(0, Math.round(el.getBoundingClientRect().top + win.scrollY - 16)); win.scrollTo({ top, behavior: 'instant' as ScrollBehavior }); scrollY.current = top;
  }, [sel]);
  useEffect(() => { wire(); }, [wire]);
  useEffect(() => { if (fromCanvas.current) fromCanvas.current = false; else if (sel) reveal(); }, [sel]);
  const onFrameLoad = useCallback(() => { const w = frame.current?.contentWindow; const y = scrollY.current;
    const put_ = () => w?.scrollTo({ top: y, behavior: 'instant' as ScrollBehavior }); put_(); requestAnimationFrame(put_); wire(); }, [wire]);
  useEffect(() => { const k = (e: KeyboardEvent) => { if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 's') { e.preventDefault(); if (dirty) save(); } }; window.addEventListener('keydown', k); return () => window.removeEventListener('keydown', k); });
  useEffect(() => { const k = (e: BeforeUnloadEvent) => { if (dirty) e.preventDefault(); }; window.addEventListener('beforeunload', k); return () => window.removeEventListener('beforeunload', k); }, [dirty]);

  if (!p) return <Loading />;
  if (!f) return <div className="card" style={{ padding: 20 }}><h1 style={{ marginTop: 0 }}>{p.meta.title}</h1><div className="notice n-info"><div>This page’s content is not in Studio yet. Import it from the <Link to="/studio/pages">Pages</Link> list.</div></div></div>;
  const status = p.status; const live = !!p.publishedRevisionId;
  const editable = can('about.update') && status !== 'in_review';
  const c: Ctx = { f, editable, set: (path, v) => { setF((x) => setAt(x!, path, v)); setDirty(true); } };
  const defs: Defs = p.context.sections ?? {};
  function showErr(e: unknown) { setErrs(e instanceof ApiError && e.details?.length ? e.details.map((d) => (d.path ? `${d.path}: ` : '') + d.message) : [e instanceof Error ? e.message : 'Something went wrong.']); }
  async function save(): Promise<boolean> {
    setBusy('save'); setErrs([]);
    try { await put(`/about/${p!.key}`, { content: f, provenance: p!.provenance }); await load(); toast(live ? 'Draft saved. The live page is unchanged until you publish.' : 'Draft saved'); return true; }
    catch (e) { showErr(e); return false; } finally { setBusy(''); }
  }
  async function act(action: string, extra: Record<string, unknown> = {}) {
    if (dirty && !(await save())) return;
    setBusy(action); setErrs([]);
    try { await post(`/about/${p!.key}/transition`, { action, ...extra }); await load(); setDialog(null); setComment('');
      toast({ submit: 'Sent for review', approve: 'Approved', request_changes: 'Changes requested', withdraw: 'Withdrawn to draft' }[action] ?? 'Done'); }
    catch (e) { setDialog(null); showErr(e); } finally { setBusy(''); }
  }
  async function publish() {
    setBusy('publish');
    try { await post(`/about/${p!.key}/publish`); await load(); setDialog(null); toast(`Published and verified on ${p!.meta.file}`); }
    catch (e) { setDialog(null); showErr(e); } finally { setBusy(''); }
  }
  async function preview() {
    if (dirty && !(await save())) return;
    setBusy('preview');
    try { const r = await post<{ url: string }>(`/about/${p!.key}/preview`); setUrl(r.url); setDialog('preview'); } catch (e) { showErr(e); } finally { setBusy(''); }
  }

  // ---- the page's parts: header, overview, fixed frames, movable sections (in their order), closing
  const movable = Object.keys(defs).filter((id) => !defs[id].fixed);
  const saved: string[] = (f.order ?? []).filter((x: string) => movable.includes(x));
  const order = [...saved, ...movable.filter((x) => !saved.includes(x))];
  const shown = (id: string) => ownCfg(c, id)?.show !== false;
  const nameOf = (id: string) => ({ hero: 'Page header', overview: 'Overview', closing: 'Closing call to action', path: 'Path heading', people: 'When no one is listed' } as Record<string, string>)[id]
    ?? (secVal(c, defs, id, 'tab') || secVal(c, defs, id, 'label') || id);
  const items: Item[] = [{ id: 'hero', label: nameOf('hero'), icon: 'log', kind: 'page' }, { id: 'overview', label: nameOf('overview'), icon: 'dash', kind: 'page' },
    ...Object.keys(defs).filter((id) => defs[id].fixed).map((id): Item => ({ id, label: nameOf(id), icon: 'layers', kind: 'fixed' })),
    ...order.map((id): Item => ({ id, label: nameOf(id), icon: ICONS[id] ?? 'layers', kind: 'section' })),
    { id: 'closing', label: nameOf('closing'), icon: 'send', kind: 'page' }];
  const move = (from: number, to: number) => { if (to < 0 || to >= order.length) return; const n = [...order]; const [x] = n.splice(from, 1); n.splice(to, 0, x); c.set(['order'], n); };
  const pillarSelect = (it: Content, i: number) => <label className="ab-inline"><span>Links to pillar</span>
    <select className="select" value={it.pillar ?? ''} onChange={(e) => c.set(['areas', i, 'pillar'], e.target.value)} aria-label={`Focus area ${i + 1}: pillar`}>
      <option value="">No link</option>{p.context.pillars.map((x) => <option key={x.key} value={x.key}>{x.name}</option>)}</select></label>;
  const pname = (k: string) => p.context.pillars.find((x) => x.key === k)?.name ?? k;
  const people = (group?: string) => <Repeat c={c} path={['people']} label={group ? 'People (all groups; this group is highlighted on the page)' : 'People'} noun="Person" max={120} blank={{ name: '', role: '', group: group ?? 'executive', bio: '', mediaId: null }}
      fields={[{ k: 'name', label: 'Full name', max: 80, required: true }, { k: 'role', label: 'Role', max: 100, placeholder: 'Role, e.g. Programme coordinator', required: true }, { k: 'bio', label: 'Short bio (optional)', max: 700, rows: 2 }]}
      head={(it, i) => <span title={p.context.groups.find((g) => g.value === it.group)?.label} style={{ opacity: group && it.group !== group ? .4 : 1 }}>{String(i + 1).padStart(2, '0')}</span>}
      extra={(it, i) => <div className="ab-person" style={{ opacity: group && it.group !== group ? .55 : 1 }}>
        <label className="ab-inline"><span>Group</span><select className="select" value={it.group} onChange={(e) => c.set(['people', i, 'group'], e.target.value)} aria-label={`Person ${i + 1}: group`}>{p.context.groups.map((g) => <option key={g.value} value={g.value}>{g.label}</option>)}</select></label>
        <Photo c={c} path={['people', i, 'mediaId']} media={media} pick={setPicking} label="Portrait" small />
      </div>} />;
  const closingFields = <><TextF c={c} path={['closing', 'title']} label="Heading" max={90} /><TextF c={c} path={['closing', 'text']} label="Text" max={300} rows={3} /></>;
  const heroFields = <><TextF c={c} path={['hero', 'title']} label="Title" max={90} big /><TextF c={c} path={['hero', 'soft']} label="Title, second part" max={90} hint="Optional, written in grey." />
    <p className="pl-title-prev" aria-label="Title preview" style={{ margin: 0 }}>{f.hero?.title} <span>{f.hero?.soft}</span></p>
    <TextF c={c} path={['hero', 'lead']} label="Line under the title" max={280} rows={3} /></>;
  const panels: Record<string, ReactNode> = { hero: heroFields, closing: closingFields };
  if (p.key === 'our-story') Object.assign(panels, {
    overview: <><TextF c={c} path={['intro']} label="Introduction" max={700} rows={5} hint="The large text in the black overview." />
      <Repeat c={c} path={['facts']} label="Key facts" noun="Fact" max={4} fields={[{ k: 'label', label: 'Label', max: 30, placeholder: 'e.g. Founded', required: true }, { k: 'value', label: 'Value', max: 60, required: true }]} />
      <Field label="Founding year" hint="Big number in the overview and the “years of community work” counter."><input className="input" type="number" min={1900} max={2100} value={f.foundedYear ?? ''} onChange={(e) => c.set(['foundedYear'], e.target.value ? Number(e.target.value) : null)} aria-label="Founding year" /></Field>
      <Paras c={c} path={['paragraphs']} label="In short (panel beside the overview)" max={600} maxItems={4} />
      <TextF c={c} path={['legalName']} label="Legal name" max={160} hint="Registration, tax and CNSS numbers are never published." />
      <Field label="Photo" hint="Optional. Replaces the “In short” panel. Shown in black and white."><Photo c={c} path={['mediaId']} media={media} pick={setPicking} label="Choose a photo" /></Field></>,
    statement: <><TextF c={c} path={['statement', 'kicker']} label="Small heading" max={80} /><TextF c={c} path={['statement', 'title']} label="Heading" max={140} />
      <Paras c={c} path={['statement', 'paragraphs']} label="Statement" max={1500} maxItems={5} hint="Leave it empty to hide the section." />
      <TextF c={c} path={['statement', 'name']} label="Name" max={80} /><TextF c={c} path={['statement', 'role']} label="Title under the name" max={100} hint="For example “President of AFCD Foundation”. Never “legal representative”." />
      <Field label="President’s photo" hint="Optional. Shown under the heading, in black and white. Choose the real photo from the Media Library; alt text is optional, e.g. “AKAYA Kamal, President of AFCD Foundation”. Leave it empty to show no photo."><Photo c={c} path={['statement', 'mediaId']} media={media} pick={setPicking} label="Choose the president’s photo" /></Field></>,
    journey: <Repeat c={c} path={['milestones']} label="Milestones, in chronological order" noun="Milestone" max={20} fields={[{ k: 'when', label: 'Date or period', max: 24, placeholder: 'e.g. 2007 or 2020–21', required: true }, { k: 'title', label: 'Title', max: 90, required: true }, { k: 'text', label: 'What happened', max: 500, rows: 2 }]} />,
    different: <Repeat c={c} path={['principles']} label="Principles" noun="Principle" max={10} fields={[{ k: 'title', label: 'Title', max: 90, required: true }, { k: 'text', label: 'Explanation', max: 500, rows: 3 }]} />,
    'what-we-do': <><Repeat c={c} path={['areas']} label="Focus areas" noun="Area" max={8} blank={{ title: '', text: '', pillar: '' }} fields={[{ k: 'title', label: 'Title', max: 90, required: true }, { k: 'text', label: 'Description', max: 700, rows: 3 }]} extra={pillarSelect} />
      <small className="muted">The core activities below the areas are a shared list, also used by the pillar pages.</small></>,
    approach: <><TextF c={c} path={['approach', 'title']} label="Statement" max={60} /><TextF c={c} path={['approach', 'soft']} label="Statement, second part" max={60} hint="Written in grey." />
      <Repeat c={c} path={['approach', 'steps']} label="Steps" noun="Step" max={6} fields={[{ k: 'title', label: 'Title', max: 40, required: true }, { k: 'text', label: 'Text', max: 260, rows: 2 }]} /></>,
    impact: <><Repeat c={c} path={['stats']} label="Numbers" noun="Number" max={6} fields={[{ k: 'value', label: 'Value', max: 12, placeholder: 'e.g. 2,700', required: true }, { k: 'label', label: 'Label', max: 60, required: true }]} />
      <small className="muted">Only figures AFCD can stand behind. End a value with + to show it as “more than”. The years counter follows the founding year (Overview).</small></>,
  });
  if (p.key === 'mission-vision') Object.assign(panels, {
    overview: <p className="muted" style={{ margin: 0 }}>The overview shows the mission and the number of values and objectives. Edit the mission in its own step.</p>,
    path: <p className="muted" style={{ margin: 0 }}>The heading above the four steps.</p>,
    mission: <TextF c={c} path={['mission']} label="Mission" max={600} rows={4} />,
    values: <Repeat c={c} path={['values']} label="Values, numbered I, II, III…" noun="Value" max={8} fields={[{ k: 'title', label: 'Name', max: 40, required: true }, { k: 'text', label: 'What it means', max: 320, rows: 2 }]} />,
    vision: <TextF c={c} path={['vision']} label="Vision" max={600} rows={4} />,
    next: <p className="muted" style={{ margin: 0 }}>Links to the Strategy &amp; Objectives page.</p>,
  });
  if (p.key === 'strategy') Object.assign(panels, {
    overview: <TextF c={c} path={['objectivesIntro']} label="Introduction" max={420} rows={4} hint="The large text in the black overview." />,
    objectives: <><Repeat c={c} path={['objectives']} label="Strategic objectives" noun="Objective" max={20} fixed head={(it) => it.ref}
        fields={[{ k: 'title', label: 'Objective', max: 180, required: true }, { k: 'text', label: 'Explanation', max: 600, rows: 3 }]}
        extra={(it) => { const keys = p.context.objectives.find((o) => o.ref === it.ref)?.pillarKeys ?? []; return <small className="muted">{keys.length ? `Pillars: ${keys.map(pname).join(', ')}` : 'Cross-cutting, all pillars'}</small>; }} />
      <small className="muted">Publishing this page also updates the objectives’ wording on projects.</small></>,
    'who-we-serve': <><TextF c={c} path={['whoIntro']} label="Introduction" max={320} rows={3} hint="Shown beside the heading when the section has no description of its own." />
      <Paras c={c} path={['summary']} label="In detail" max={1000} maxItems={5} />
      <small className="muted">The list of participant groups is shared with the pillar pages.</small></>,
    'where-we-work': <><Repeat c={c} path={['regions']} label="Regions" noun="Region" max={16} fields={[{ k: 'name', label: 'Region', max: 60, required: true }, { k: 'places', label: 'Places', max: 260 }]} />
      <TextF c={c} path={['coverage']} label="Coverage note" max={1000} rows={4} hint="The public city is Marrakech; the street address is never published." /></>,
  });
  if (p.key === 'team') Object.assign(panels, {
    overview: <TextF c={c} path={['intro']} label="Introduction" max={700} rows={5} hint="The large text in the black overview." />,
    people: <><p className="muted" style={{ margin: 0 }}>Shown instead of the groups while no one is listed. The message is the section’s description.</p>{people()}</>,
    ...Object.fromEntries(p.context.groups.map((g) => [g.value, people(g.value)])),
  });
  if (p.key === 'partners') Object.assign(panels, {
    overview: <TextF c={c} path={['hero', 'lead']} label="Introduction" max={280} rows={4} hint="The large text in the black overview." />,
    directory: <><TextF c={c} path={['directoryIntro']} label="Line above the directory" max={260} rows={2} />
      <Link className="btn btn-sm" to="/studio/partners" style={{ justifySelf: 'start' }}><Icon n="partner" />Edit the organisations in Partners</Link></>,
    models: <Repeat c={c} path={['models']} label="Partnership models" noun="Model" max={6} fields={[{ k: 'title', label: 'Title', max: 40, required: true }, { k: 'text', label: 'Text', max: 320, rows: 2 }]} />,
    how: <Repeat c={c} path={['steps']} label="Steps" noun="Step" max={6} fields={[{ k: 'title', label: 'Title', max: 80, required: true }, { k: 'text', label: 'Text', max: 320, rows: 2 }]} />,
  });
  const selItem = items.find((x) => x.id === sel) ?? null;
  const scale = Math.min(1, Math.max(0.1, (size.w - 32) / device)); const canvasH = Math.max(400, size.h - 40);
  const chip = status === 'in_review' ? { t: 'In review · read-only', tone: 'muted' } : status === 'approved' ? { t: 'Approved · ready to publish', tone: 'ok' }
    : dirty ? null : p.problems.length ? { t: `${p.problems.length} to fix before review`, tone: 'warn' } : ['draft', 'changes_requested'].includes(status) ? { t: 'Ready for review', tone: 'ok' } : null;

  return <div className="builder ab-builder">
    <div className="b-bar">
      <button className="btn btn-ghost icon-btn" onClick={() => navigate('/studio/pages')} aria-label="Back to Pages" title="Back to Pages"><Icon n="chev" style={{ transform: 'rotate(180deg)' }} /></button>
      <div className="b-title"><b>{p.meta.title}</b><span className="mono muted">{p.meta.file}</span></div>
      <span className="pills">{live && status !== 'published' && <LiveBadge />}<Badge s={status} /></span>
      <span className="muted" role="status" style={{ fontSize: 12 }}>{busy === 'save' ? 'Saving…' : dirty ? 'Unsaved changes' : 'All changes saved'}</span>
      {chip && <span className={`b-chip is-${chip.tone}`} title={chip.tone === 'warn' ? p.problems.join(' · ') : undefined}>{chip.t}</span>}
      <span style={{ flex: 1 }} />
      <div className="seg" role="group" aria-label="Device">{DEVICES.map(([w, ic, l]) => <button key={w} className={device === w ? 'on' : ''} onClick={() => setDevice(w)} title={l} aria-label={l}><Icon n={ic} width={15} height={15} style={{ verticalAlign: -3 }} /></button>)}</div>
      <button className="btn btn-ghost" onClick={() => setDialog('history')}><Icon n="history" />History</button>
      <button className="btn" onClick={preview} disabled={!!busy}><Icon n="eye" />{busy === 'preview' ? 'Building…' : 'Preview'}</button>
      {editable && <button className="btn" onClick={save} disabled={!dirty || !!busy} title="Save (⌘S)"><Icon n="save" />Save</button>}
      {['draft', 'changes_requested'].includes(status) && can('about.update') && <button className="btn btn-primary" disabled={!!busy || (!dirty && p.problems.length > 0)} onClick={() => act('submit')}><Icon n="send" />Submit for review</button>}
      {status === 'in_review' && can('about.approve') && <><button className="btn" onClick={() => setDialog('changes')}>Request changes</button><button className="btn btn-ok" disabled={!!busy} onClick={() => act('approve')}><Icon n="check" />Approve</button></>}
      {status === 'approved' && can('about.publish') && <button className="btn btn-ok" onClick={() => setDialog('publish')}><Icon n="rocket" />Publish</button>}
      {['in_review', 'approved'].includes(status) && can('about.update') && <button className="btn btn-ghost" onClick={() => act('withdraw')}><Icon n="undo" />Withdraw</button>}
    </div>
    {errs.length > 0 && <div className="notice n-warn b-notice" role="alert"><div><ul style={{ margin: 0 }}>{errs.map((x) => <li key={x}>{x}</li>)}</ul></div><button className="btn btn-ghost icon-btn btn-sm" onClick={() => setErrs([])} aria-label="Dismiss"><Icon n="x" /></button></div>}
    {status === 'changes_requested' && <div className="notice n-warn b-notice" role="status"><div><b>Changes requested.</b> Update the page, then submit it again.{p.history.comments.filter((x) => x.kind === 'request_changes' && x.body).slice(0, 1).map((x) => <q key={x.id} style={{ marginLeft: 6 }}>{x.body}</q>)}</div></div>}

    <div className="b-body">
      <aside className="b-left">
        <div className="between" style={{ padding: '10px 12px 6px' }}><b style={{ fontSize: 13 }}>Sections</b><small className="muted">Drag or ↑↓ to reorder</small></div>
        <ol className="b-scroll b-layers" aria-label={`${p.meta.title} sections`}>{items.map((it) => {
          const i = order.indexOf(it.id); const movableIt = it.kind === 'section'; const on = !movableIt || shown(it.id);
          return <li key={it.id} className={`b-layer${sel === it.id ? ' on' : ''}${on ? '' : ' off'}`} draggable={editable && movableIt}
            onDragStart={(ev) => { ev.dataTransfer.setData('text/plain', String(i)); ev.dataTransfer.effectAllowed = 'move'; }}
            onDragOver={(ev) => { if (editable && movableIt) { ev.preventDefault(); ev.currentTarget.classList.add('drop'); } }} onDragLeave={(ev) => ev.currentTarget.classList.remove('drop')}
            onDrop={(ev) => { ev.preventDefault(); ev.currentTarget.classList.remove('drop'); if (movableIt) move(Number(ev.dataTransfer.getData('text/plain')), i); }}>
            <button className="b-layer-main" onClick={() => { if (sel === it.id) reveal(); else setSel(it.id); }} aria-current={sel === it.id}>
              <span className="b-grip" aria-hidden="true">{movableIt ? '⋮⋮' : ''}</span>
              <span className="hp-num" aria-hidden="true">{movableIt ? String(i + 1).padStart(2, '0') : '–'}</span>
              <Icon n={it.icon} width={15} height={15} />
              <span className="min-w-0"><b>{it.label}</b><small>{it.kind === 'section' ? (on ? (ownCfg(c, it.id) && Object.keys(ownCfg(c, it.id)!).some((k) => k !== 'show') ? 'Section · edited' : 'Section') : 'Hidden') : it.kind === 'fixed' ? 'Frame' : 'Page'}</small></span>
            </button>
            {movableIt && editable && <span className="b-layer-act ab-layer-act">
              <button className="b-more" onClick={() => setSec(c, defs, it.id, 'show', !on)} title={on ? 'Hide this section' : 'Show this section'} aria-label={`${on ? 'Hide' : 'Show'} ${it.label}`}><Icon n={on ? 'eye' : 'eyeoff'} width={14} height={14} /></button>
              <button className="b-more" disabled={i === 0} onClick={() => move(i, i - 1)} aria-label={`Move ${it.label} up`}>↑</button>
              <button className="b-more" disabled={i === order.length - 1} onClick={() => move(i, i + 1)} aria-label={`Move ${it.label} down`}>↓</button>
            </span>}
          </li>;
        })}</ol>
      </aside>

      <div className="b-canvas" ref={box} onClick={() => setSel(null)}>
        <div className="b-device" style={{ width: device * scale, height: canvasH }} onClick={(ev) => ev.stopPropagation()}>
          {html ? <iframe ref={frame} title={`${p.meta.title} canvas`} srcDoc={html} onLoad={onFrameLoad} style={{ width: device, height: canvasH / scale, zoom: scale }} /> : <Loading />}
        </div>
        <span className="b-zoom">{device}px · {Math.round(scale * 100)}% · click a section of the page to edit it</span>
      </div>

      <aside className="b-right">
        {!selItem ? <div className="b-scroll stack" style={{ padding: 16 }}>
          <p className="muted" style={{ margin: 0 }}>Select a section in the list or on the page to edit it.</p>
          {p.problems.length > 0 && <div className="ed-check"><b>{p.problems.length} thing{p.problems.length === 1 ? '' : 's'} to do before review</b><ul>{p.problems.map((x) => <li key={x}>{x}</li>)}</ul></div>}
          <dl className="kv"><dt>Website</dt><dd>{live ? `Live${status !== 'published' ? ' · newer draft' : ''}` : 'Not from Studio yet'}</dd><dt>Page</dt><dd className="mono">{p.meta.file}</dd>{p.publishedAt && <><dt>Published</dt><dd>{fmtDate(p.publishedAt)}</dd></>}</dl>
          {live && <a className="btn btn-sm" href={me.siteUrl + p.meta.file} target="_blank" rel="noopener" style={{ justifySelf: 'start' }}><Icon n="ext" />Open the live page</a>}
          <Field label="Source (internal)" hint="Where this content comes from. Not shown on the website."><input className="input" maxLength={300} value={p.provenance} disabled={!editable} onChange={(e) => { setP({ ...p, provenance: e.target.value }); setDirty(true); }} aria-label="Source" /></Field>
        </div>
        : <fieldset className="b-scroll b-insp stack" disabled={!editable}>
          <div><small className="muted">{selItem.kind === 'section' ? 'Section' : selItem.kind === 'fixed' ? 'Frame' : 'Page'}</small><h3 style={{ margin: '2px 0 0', fontSize: 16 }}>{selItem.label}</h3></div>
          {selItem.kind === 'section' && <label className="check"><input type="checkbox" checked={shown(selItem.id)} onChange={(e) => setSec(c, defs, selItem.id, 'show', e.target.checked)} /><span>Show on the page</span></label>}
          {panels[selItem.id]}
          {defs[selItem.id] && <SectionTexts c={c} defs={defs} id={selItem.id} />}
        </fieldset>}
      </aside>
    </div>

    {picking && <MediaPicker onClose={() => setPicking(null)} onPick={(m) => { if (m[0]) { setMedia((x) => new Map(x).set(m[0].id, m[0])); c.set(picking, m[0].id); } setPicking(null); }} />}
    {dialog === 'preview' && <Modal wide title={`Preview · ${p.meta.file} built by the real website build`} onClose={() => setDialog(null)}><div className="preview-wrap"><iframe title="Page preview" src={url} style={{ width: Math.min(device, window.innerWidth - 80) }} /></div></Modal>}
    {dialog === 'history' && <Modal title="History" onClose={() => setDialog(null)}><div className="modal-b">
      {p.history.revisions.length === 0 ? <p className="muted">No revisions yet.</p> : <ol className="timeline">{p.history.revisions.slice(0, 12).map((r) => <li key={r.id}><b>Revision {r.number} · {r.reason}{r.id === p.publishedRevisionId ? ' · live' : ''}</b><small>{fmtDate(r.createdAt)}</small>
        {editable && r.id !== p.history.revisions[0]?.id && <button className="btn btn-sm btn-ghost" style={{ padding: 0, height: 'auto' }} onClick={async () => { if (confirm(`Copy revision ${r.number} into the draft?`)) { await post(`/about/${p.key}/revisions/${r.id}/restore`); await load(); setDialog(null); toast('Revision restored as a draft'); } }}>Restore this version</button>}</li>)}
        {p.history.comments.filter((x) => x.body).slice(0, 5).map((x) => <li key={x.id}><b>{x.kind.replace('_', ' ')}</b><q>{x.body}</q><small>{fmtDate(x.createdAt)}</small></li>)}</ol>}
    </div></Modal>}
    {dialog === 'changes' && <Modal size="sm" title="Request changes" onClose={() => setDialog(null)} footer={<><button className="btn" onClick={() => setDialog(null)}>Cancel</button><button className="btn btn-primary" disabled={!comment.trim()} onClick={() => act('request_changes', { comment })}>Send to author</button></>}><div className="modal-b"><textarea className="textarea" autoFocus aria-label="What needs to change" value={comment} onChange={(e) => setComment(e.target.value)} /></div></Modal>}
    {dialog === 'publish' && <Modal size="sm" title={`Publish ${p.meta.title}?`} onClose={() => !busy && setDialog(null)} footer={<><button className="btn" disabled={!!busy} onClick={() => setDialog(null)}>Cancel</button><button className="btn btn-ok" disabled={!!busy} onClick={publish}><Icon n="rocket" />{busy ? 'Publishing and checking…' : 'Publish'}</button></>}>
      <div className="modal-b"><p style={{ margin: 0 }}>Rebuilds <span className="mono">{p.meta.file}</span>{p.key === 'our-story' ? ' and the About hub' : ''}{p.key === 'strategy' ? ', updates the wording of the strategic objectives everywhere,' : ''} and checks the result.</p></div></Modal>}
  </div>;
}
